from typing import List

class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        INF = float('inf')
        d = [[INF] * 26 for _ in range(26)]
        for i in range(26):
            d[i][i] = 0
        for o, c, w in zip(original, changed, cost):
            a = ord(o) - ord('a')
            b = ord(c) - ord('a')
            if w < d[a][b]:
                d[a][b] = w
        for k in range(26):
            dk = d[k]
            for i in range(26):
                dik = d[i][k]
                if dik == INF:
                    continue
                di = d[i]
                for j in range(26):
                    nv = dik + dk[j]
                    if nv < di[j]:
                        di[j] = nv
        total = 0
        for s, t in zip(source, target):
            if s == t:
                continue
            a = ord(s) - ord('a')
            b = ord(t) - ord('a')
            if d[a][b] == INF:
                return -1
            total += d[a][b]
        return total
