    m = draw(st.integers(1, 6))
    pairs = [(a, b) for a in ALPHA for b in ALPHA if a != b]
    chosen = [draw(st.sampled_from(pairs)) for _ in range(m)]
    original = [p[0] for p in chosen]
    changed = [p[1] for p in chosen]
    cost = [draw(st.integers(1, 10)) for _ in range(m)]
    return "\n".join([
        json.dumps(source),
        json.dumps(target),
        json.dumps(original),
        json.dumps(changed),
        json.dumps(cost),
    ])


