import json
from hypothesis import strategies as st

_INF = 10 ** 18


@st.composite
def gen(draw):
    n = draw(st.integers(1, 6))
    alpha = draw(st.sampled_from(["ab", "abc", "abcd", "abcdefghijklmnopqrstuvwxyz"]))
    source = draw(st.text(alphabet=alpha, min_size=n, max_size=n))
    target = draw(st.text(alphabet=alpha, min_size=n, max_size=n))
    k = draw(st.integers(1, 8))
    original = []
    changed = []
    cost = []
    for _ in range(k):
        x = draw(st.sampled_from(list(alpha)))
        y = draw(st.sampled_from([c for c in alpha if c != x]))
        original.append(x)
        changed.append(y)
        cost.append(draw(st.integers(1, 20)))
    return "\n".join([
        json.dumps(source),
        json.dumps(target),
        json.dumps(original),
        json.dumps(changed),
        json.dumps(cost),
    ])


def _parse(inp):
    lines = inp.strip().split("\n")
    if len(lines) != 5:
        raise ValueError("bad line count")
    return [json.loads(l) for l in lines]


def validate(inp: str) -> bool:
    try:
        source, target, original, changed, cost = _parse(inp)
        if not (isinstance(source, str) and isinstance(target, str)):
            return False
        n = len(source)
        if not (1 <= n <= 10 ** 5) or len(target) != n:
            return False
        if not all(c.isascii() and c.islower() and c.isalpha() for c in source + target):
            return False
        m = len(cost)
        if not (1 <= m <= 2000) or len(original) != m or len(changed) != m:
            return False
        for o, c in zip(original, changed):
            if not (isinstance(o, str) and isinstance(c, str)):
                return False
            if len(o) != 1 or len(c) != 1:
                return False
            if not (o.isascii() and o.islower() and o.isalpha()):
                return False
            if not (c.isascii() and c.islower() and c.isalpha()):
                return False
            if o == c:
                return False
        for z in cost:
            if not (isinstance(z, int) and not isinstance(z, bool)):
                return False
            if not (1 <= z <= 10 ** 6):
                return False
        return True
    except Exception:
        return False


def ref(inp: str) -> str:
    source, target, original, changed, cost = _parse(inp)
    # Direct edge costs (minimum over parallel edges).
    dist = [[_INF] * 26 for _ in range(26)]
    for i in range(26):
        dist[i][i] = 0
    for o, c, z in zip(original, changed, cost):
        a = ord(o) - 97
        b = ord(c) - 97
        if z < dist[a][b]:
            dist[a][b] = z
    # Shortest paths between letters (Floyd-Warshall, exhaustive relaxation).
    for m in range(26):
        for i in range(26):
            for j in range(26):
                if dist[i][m] + dist[m][j] < dist[i][j]:
                    dist[i][j] = dist[i][m] + dist[m][j]
    total = 0
    for s, t in zip(source, target):
        if s == t:
            continue
        d = dist[ord(s) - 97][ord(t) - 97]
        if d >= _INF:
            return json.dumps(-1)
        total += d
    return json.dumps(total)
